mapper.select:
SELECT
    
FROM sys_user
WHERE tenant_key = #{tenantKey}
  AND deleted_at = 0
  AND (
      feishu_open_id = #{openId}
      
          OR feishu_union_id = #{unionId}
      
  )
ORDER BY CASE WHEN feishu_open_id = #{openId} THEN 0 ELSE 1 END
LIMIT 1

mapper.update:
UPDATE sys_user
SET mfa_last_used_counter = #{counter}
WHERE id = #{userId}
  AND mfa_status = 1
  AND (mfa_last_used_counter IS NULL OR mfa_last_used_counter < #{counter})
  AND deleted_at = 0
